// maAI = "AI code", dongLoi = "faulty lines", don = "order", gio = "hour"
const maAI = [
  "function xuLyDon(don, gio, ma) {",
  "  const tong = tongTien(gio);",
  "  const phi = phiGiao(tong);",
  "  const sauGiam = apGiamGia(tong, ma);",
  "  const tamTinh = sauGiam + phi;",
  "  if (don.gio <= 7 || don.gio > 21) return 'outside opening hours';",
  "  return Math.roundTo(tamTinh, 1000);",
  "}",
];
maAI.forEach((dong, i) => console.log((i + 1) + "| " + dong));

// Write the numbers of the lines you think have a mistake, for example [2, 5].
const dongLoi = [];

// ---- Scoring part, no need to read or change ----
const thatSu = { 3: "calculates the delivery fee before the discount", 6: "wrongly rejects 7:00, because <= is used instead of <", 7: "Math.roundTo does not exist" };
let dung = 0;
let nham = 0;
for (const n of new Set(dongLoi)) {
  if (thatSu[n]) dung++;
  else nham++;
}
console.log("Found " + dung + "/3 mistakes, wrongly flagged " + nham + " healthy lines.");
for (const n of [...new Set(dongLoi)].sort((a, b) => a - b)) {
  if (thatSu[n]) console.log("Line " + n + ": " + thatSu[n]);
}

